BEGIN;
DO $qa$
DECLARE m uuid:=gen_random_uuid(); u uuid:=gen_random_uuid(); p uuid:=gen_random_uuid(); x uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); b2 uuid:=gen_random_uuid(); a bigint; t bigint; n bigint; restored bigint; c1 bigint; c2 bigint; c3 bigint; cr bigint; public_id bigint; r jsonb; cards jsonb:='[{"metric":"orders_today","label":"QA original","size":"normal","tone":"default"}]'; style jsonb:='{"font":"tahoma","logoAsset":"mark","logoDarkAsset":"brand","logoWidth":"40%","logoPosition":"cover","dialogRadius":"round","dashboardPanels":{"activity":false},"elements":{"dashboard_status":[{"key":"dashboard_status_tag","shape":"pack","size":"normal","font":"tahoma"}]}}';
BEGIN
 INSERT INTO auth.users(id) VALUES(m),(u),(p),(x);
 INSERT INTO public.ff_profiles(user_id,display_name,role,active) VALUES(m,'QA STEP08 manager','manager',true),(u,'QA STEP08 worker','cashier',true),(p,'QA STEP08 peer','cashier',true),(x,'QA STEP08 outsider','cashier',true) ON CONFLICT(user_id) DO UPDATE SET role=excluded.role,active=true;
 INSERT INTO public.ff_branches(id,code,name) VALUES(b,'qa-step08-'||b,'QA STEP08 A'),(b2,'qa-step08-'||b2,'QA STEP08 B');
 INSERT INTO public.ff_user_branches(user_id,branch_id) VALUES(u,b),(p,b),(x,b2);
 PERFORM set_config('request.jwt.claim.sub',m::text,true); SET LOCAL ROLE authenticated;
 a:=public.ff_a07_named_design('dashboard','cashier',b,'mobile','D02','QA original','icons','QA original','',cards,style);
 r:=public.ff_step08_release_impact('design',a);
 IF r->>'valid'<>'true' OR (r->>'target_count')::int<>2 OR NOT(r->'targets' @> jsonb_build_array(jsonb_build_object('account_id',u))) THEN RAISE EXCEPTION 'design impact %',r;END IF;
 PERFORM public.ff_ui_publish(a);
 t:=public.ff_a07_named_design('dashboard','cashier',b,'mobile','D05','QA experiment','wide','QA trial','',NULL,'{"font":"serif","logoAsset":"brand"}');
 n:=public.ff_a07_named_design('dashboard','cashier',b,'mobile','D06','','floating','QA other','',NULL,'{}');
 IF (SELECT count(*) FROM public.ff_ui_trial_accounts(t))<>2 OR EXISTS(SELECT FROM public.ff_ui_trial_accounts(t) WHERE account_id=x) THEN RAISE EXCEPTION 'trial accounts leak';END IF;
 IF public.ff_ui_control_trial(t,ARRAY[u],1)<>1 THEN RAISE EXCEPTION 'trial start';END IF;
 PERFORM set_config('request.jwt.claim.sub',u::text,true);
 IF (public.ff_a07_effective_designs(b,'mobile')->'dashboard'->>'id')::bigint IS DISTINCT FROM t THEN RAISE EXCEPTION 'trial not effective';END IF;
 IF (public.ff_a07_effective_designs(b,'desktop')->'dashboard'->>'id')::bigint IN(a,t) THEN RAISE EXCEPTION 'trial device leak';END IF;
 PERFORM set_config('request.jwt.claim.sub',p::text,true);
 IF (public.ff_a07_effective_designs(b,'mobile')->'dashboard'->>'id')::bigint IS DISTINCT FROM a THEN RAISE EXCEPTION 'trial account leak';END IF;
 PERFORM set_config('request.jwt.claim.sub',x::text,true);
 IF (public.ff_a07_effective_designs(b2,'mobile')->'dashboard'->>'id')::bigint IN(a,t) THEN RAISE EXCEPTION 'trial branch leak';END IF;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);PERFORM public.ff_ui_publish(n);
 IF public.ff_step08_release_impact('design',t)->>'valid' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'stale draft valid';END IF;
 BEGIN PERFORM public.ff_ui_control_trial(t,ARRAY[u],1);RAISE EXCEPTION 'stale trial allowed' USING ERRCODE='XX000';EXCEPTION WHEN raise_exception OR invalid_parameter_value THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',u::text,true);
 IF (public.ff_a07_effective_designs(b,'mobile')->'dashboard'->>'id')::bigint IS DISTINCT FROM n THEN RAISE EXCEPTION 'stale trial survived publish';END IF;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);restored:=public.ff_ui_rollback(n);
 PERFORM set_config('request.jwt.claim.sub',u::text,true);r:=public.ff_a07_effective_designs(b,'mobile')->'dashboard';
 IF (r->>'id')::bigint IS DISTINCT FROM restored OR r->>'pack'<>'D02' OR r->>'bar'<>'icons' OR r->'card_layout' IS DISTINCT FROM cards OR NOT(r->'style_config' @> style) THEN RAISE EXCEPTION 'restore mismatch %',r;END IF;
 BEGIN PERFORM public.ff_step08_release_impact('design',restored);RAISE EXCEPTION 'nonmanager impact' USING ERRCODE='XX000';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);
 c1:=public.ff_content_create_draft('cashier.title','cashier',b,'QA content original');PERFORM public.ff_content_publish(c1);
 c2:=public.ff_content_create_draft('cashier.title','cashier',b,'QA content trial');c3:=public.ff_content_create_draft('cashier.title','cashier',b,'QA content final');
 r:=public.ff_step08_release_impact('content',c2);
 IF r->>'trial_allowed'<>'true' OR (r->>'target_count')::int<>2 THEN RAISE EXCEPTION 'content impact %',r;END IF;
 BEGIN PERFORM public.ff_step08_content_trial(c2,ARRAY[x],1);RAISE EXCEPTION 'foreign trial allowed' USING ERRCODE='XX000';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 IF public.ff_step08_content_trial(c2,ARRAY[u],1)<>1 THEN RAISE EXCEPTION 'content trial start';END IF;
 PERFORM set_config('request.jwt.claim.sub',u::text,true);
 IF NOT EXISTS(SELECT FROM public.ff_content_effective(b) WHERE content_key='cashier.title' AND revision=c2) THEN RAISE EXCEPTION 'content trial not visible';END IF;
 PERFORM set_config('request.jwt.claim.sub',p::text,true);
 IF NOT EXISTS(SELECT FROM public.ff_content_effective(b) WHERE content_key='cashier.title' AND revision=c1) THEN RAISE EXCEPTION 'content trial leak';END IF;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);PERFORM public.ff_content_publish(c3);
 IF public.ff_step08_release_impact('content',c2)->>'valid' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'stale text';END IF;
 PERFORM set_config('request.jwt.claim.sub',u::text,true);
 IF NOT EXISTS(SELECT FROM public.ff_content_effective(b) WHERE content_key='cashier.title' AND revision=c3) THEN RAISE EXCEPTION 'content final not propagated';END IF;
 BEGIN PERFORM public.ff_step08_content_restore(c3);RAISE EXCEPTION 'unauthorized restore' USING ERRCODE='XX000';EXCEPTION WHEN raise_exception OR insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);cr:=public.ff_step08_content_restore(c3);
 PERFORM set_config('request.jwt.claim.sub',p::text,true);
 IF NOT EXISTS(SELECT FROM public.ff_content_effective(b) WHERE content_key='cashier.title' AND revision=cr AND body='QA content original') THEN RAISE EXCEPTION 'content restore mismatch';END IF;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);public_id:=public.ff_content_create_draft('login.title','all',NULL,'QA public text');
 IF public.ff_step08_release_impact('content',public_id)->>'trial_allowed' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'public trial allowed';END IF;
 -- Unsafe properties, unknown KPI/action, missing protected elements, and client audit forgery.
 BEGIN PERFORM public.ff_a07_named_design('dashboard','cashier',b,'mobile','D01','','labels','QA unsafe','',NULL,'{"quickActions":["unknown_rpc"]}');RAISE EXCEPTION 'unknown action accepted' USING ERRCODE='XX000';EXCEPTION WHEN raise_exception OR check_violation THEN NULL;END;
 BEGIN PERFORM public.ff_a07_named_design('dashboard','cashier',b,'mobile','D01','','labels','QA unsafe','',NULL,'{"elements":{"dashboard_status":[]}}');RAISE EXCEPTION 'required element hidden' USING ERRCODE='XX000';EXCEPTION WHEN raise_exception OR check_violation THEN NULL;END;
 BEGIN PERFORM public.ff_a07_named_design('dashboard','cashier',b,'mobile','D01','','labels','QA unsafe','', '[{"metric":"secret","label":"QA","size":"normal","tone":"default"}]','{}');RAISE EXCEPTION 'unknown KPI accepted' USING ERRCODE='XX000';EXCEPTION WHEN raise_exception OR check_violation THEN NULL;END;
 BEGIN PERFORM public.ff_content_create_draft('cashier.title','cashier',b,'<script>bad</script>');RAISE EXCEPTION 'unsafe text accepted' USING ERRCODE='XX000';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN PERFORM public.ff_step08_content_trial(public_id,ARRAY[u],1);RAISE EXCEPTION 'public trial accepted' USING ERRCODE='XX000';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN INSERT INTO public.ff_audit_log(actor_id,action,entity_type,entity_id,branch_id,details) VALUES(m,'step08_content_publish','content',public_id::text,b,'{}');RAISE EXCEPTION 'client forged audit accepted' USING ERRCODE='XX000';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 RESET ROLE;
 IF NOT EXISTS(SELECT FROM public.ff_audit_log WHERE actor_id=m AND action='a07_design_publish' AND entity_id=restored::text AND details->'targets' @> to_jsonb(ARRAY[u,p])) THEN RAISE EXCEPTION 'design targets missing';END IF;
 IF NOT EXISTS(SELECT FROM public.ff_audit_log WHERE actor_id=m AND action='step08_content_restore' AND entity_id=cr::text) OR NOT EXISTS(SELECT FROM public.ff_audit_log WHERE actor_id=m AND action='step08_content_publish' AND entity_id=cr::text AND details->'targets' @> to_jsonb(ARRAY[u,p])) OR NOT EXISTS(SELECT FROM public.ff_audit_log WHERE actor_id=m AND action='step08_content_trial_stop' AND entity_id=c2::text) THEN RAISE EXCEPTION 'text lifecycle audit missing';END IF;
 IF has_table_privilege('authenticated','ff_private.step08_content_trials','SELECT') OR has_function_privilege('anon','public.ff_step08_release_impact(text,bigint)','EXECUTE') THEN RAISE EXCEPTION 'unsafe ACL';END IF;
END $qa$;
ROLLBACK;
SELECT 'PASS STEP08 lifecycle scope stale trial restore audit ACL rollback' result;
